custom_css:
/*Header*/
.hamburger-icon{
    height: 57px;
    width: 62px;
    position: relative;
    border: 2px solid #354476;
    border-radius: 10px;
}

.hamburger-icon span{
    margin-top: 18px;
    margin-left: 14px;
    width:50%;
    background: #fff !important;
}
.hamburger-icon.open{
    border:none !important;
}
.navbar-header .shopping-container{
    padding: 15px;
    border: 2px solid #354476;
    border-radius: 10px;
}
.fixed-header {
    border-top: none;
}

.mpc-divider-wrap{
    display:none;
}
.fixed-header > .container{
    padding-top:.9em;
    padding-bottom:.9em;
}
/*Product*/
.single-product-booking .product-side-information-inner .product_meta .tagged_as a{
    color: #a7acbf;
    text-transform: initial;
}
.tagged_as{
    color: #121f49;
    font-size: 15px;
    font-weight: 600;
    margin-top: 20px;
}

.posted_in{
    display: none !important;
}
.product-content .compare:before,
.single-product-booking .product-side-information-inner .yith-wcwl-add-to-wishlist a:not(.alt):before{
    color: #121f49;
}
.breadcrumbs,
.woocommerce-breadcrumb{
    margin-bottom: 0px;    
}
.single-product-booking .product-side-information-inner .yith-wcwl-add-to-wishlist a:not(.alt),
.compare.button{
    font-size: 15px;
    font-weight: 600;
    color: #121f49;
    letter-spacing: 0;
}
.single-product .minus{
    margin-right:-5px;
}
.single-product .plus{
    margin-left:-5px;
}
.single-product .minus:hover,
.single-product .plus:hover{
    background:#354476 !important;
    border-color:#354476 !important;
}
.single-product .minus,
.single-product .plus,
.single-product .input-text.qty{
    border: 1px solid #cccfdb !important;
}
.product-share ul li a {
    padding: 3px 10px;
    color: #b6b8b8;
}
.product-share ul li a:hover {
    color: #121f49;
}
.single-product .add_to_cart_button.ajax_add_to_cart{
    background: #fff;
    border: 2px solid #354476;
    border-radius: 8px;
    color: #354476;
    font-size: 15px;
    text-transform: inherit;
    letter-spacing: 0;
    font-weight: 400;
    width: 170px !important;
    min-width: 120px;
    margin-bottom: 15px;
    margin-top:15px;
}
.single-product .add_to_cart_button.ajax_add_to_cart:hover{
    background: #354476;
    color:#fff;
}
.product-side-information-inner .woocommerce-Price-amount{
    font-size: 50px !important;
    color: #354476 !important;
    font-weight: 500 !important;
}
.single-product .product-price-title{
    display:none !important;
}
.single-product-booking .product-side-information-inner > div {
    background-color: #fff;
    padding: 0;
    margin-bottom: 15px;
}
.short-description .wpb_text_column > .wpb_wrapper > p:first-child{
    margin-bottom:0;
    margin-top:-4px;
}
.product-information .product_title{
    font-size: 24px;
    font-weight: 200;
    text-transform: initial;
}
.single-product .product-information-inner  .title{
    font-weight:500;
}
.single-product .product-information{
    text-align:center;
}
.product-information .short-description p{
    line-height: 36px;
    font-size: 16px;
}
/*Content*/

.price-block p{
    margin-bottom:30px;
}
.weight-200{
    font-weight:300 !important;
}
.content-page, .page-content {
    padding-bottom: 0;
}
.border__bottom:after{
    content:" ";
    width: 176px;
    height: 2px;
    display: block;
    background: #a7acbf;
    position: relative;
    top: -14px;
    left: 20px;
}
.initial{
 text-transform:initial !important;   
}

/*Blog*/
.single-post .comment-respond{
    display:none;
}
.blog article,
.single-post .post-heading{
    text-align:center;
}
.blog footer.footer{
    margin-top:85px;
}
.blog .post-categories{
    border-radius: 0 8px 8px 0 !important;
}
.media-body h4.media-heading{
    font-size: 18px;
    color: #354476;
}
.share-post .menu-social-icons li a {
    padding: 0 8px;
    color: #a7acbf;
}
.share-post .menu-social-icons li a:hover {
    color: #263051;
}
.single-post .page-heading h1 > span{
    line-height: 45px !important;
    font-size: 40px !important;
}
.single-post #breadcrumb{
    font-size:15px;
}
.vcard a{
    color: #354476 !important;
}
.content-article p {
    font-size: 15px;
    line-height: 1.6;
    font-weight: 200;
}
.share-post > span.share-title{
    text-transform: inherit;
    color: #354476;
    font-size: 24px;
    letter-spacing: 0;
    font-weight:600;
}
.post-categories a{
    font-family: Kanit;
    font-weight: 600;
    font-size: 12px;
}
.single-post .wp-picture.blog-hover-default{
    margin-bottom:50px;
}
.single-post .post-heading h2 {
    text-transform: uppercase;
    font-weight: 400;
    letter-spacing: 0.02em;
    color: #354476;
    font-size: 36px;
}
.single-post .meta-post * {
    font-size: 18px;
    font-weight: 200;
    color: #c3c3c3;
}
.home-blog-image{
    min-height:300px !important;
}
.single-post .post-header .post-categories{
    left: 45%;
    border-radius:8px !important;
}
.blog .meta-post,
.blog .meta-post *{
    font-size: 16px;
    font-weight: 200;
    color: #c3c3c3;
}
.post-heading {
    margin-bottom: 15px;
}
.blog .meta-post {
    margin-bottom:4px;
}

.blog h2 a{
    font-size: 18px;
    text-transform: uppercase;
    letter-spacing: 0;
    line-height: 26px;
    color: #354476;
}
/*footer*/

footer.footer .mc4wp-form{
    max-width:300px;
}
body .mc4wp-form input[type=email]::placeholder{
    color:#a7acbf !important;
    font-size:12px;
}
body .mc4wp-form input[type=email] {
    height: 36px !important;
    border-bottom: 1px solid #374571;
    border-top:none;
    border-left:none;
    border-right:none;
    padding: 0 25px;
    font-size: 12px;
    width:95%;
    background: transparent;
    color:#fff;
}
body .mc4wp-form-fields input[type="submit"]:hover{
    background:#3c3c3c !important;
    color:#fff !important;
}
body .mc4wp-form-fields input[type="submit"]:hover{
    background:#374571 !important;
}
body .mc4wp-form-fields input[type="submit"] {
    padding: 0;
    width: 90px;
    color: #fff;
    height: 36px;
    border: 1px solid #374571 !important;
    border-radius: 9px !important;
    position: absolute;
    top: 0px;
    bottom: 0;
    right: 0;
    background: transparent !important;
    font-size: 9px;
    font-weight: 600;
}
.footer-widgets > p{
    display:none;
}
.et-follow-buttons.buttons-size-normal > a{
    margin-right:15px;
    width: 23px;
    height: 24px;
    border-radius: 4px;
    padding: 0;
    margin-top:11px;
}
.footer-link p,
.services-link p{
    margin-bottom:4px;
    cursor:pointer;
    font-size:13px !important;
}
.footer-link p:hover,
.services-link p:hover{
   color:#fff;
}
.mobile-block{
    display:none;
}



/*responsive*/
@media only screen and (max-width: 480px) {
    body .price-block{
        background-color:#fff !important;
    }
    .price-block > .text-center{
        margin-bottom:10px !important;
    }
    .responsive-none{
        display:none !important;
    }
    .mobile-block{
        display:block;
    }
    .navbar-header .shopping-container {
       padding: 0;
       border: none;
       border-radius: 0;
       top: 0 !important;
    }
    .single-post .page-heading h1 > span {
       line-height: 36px !important;
       font-size: 30px !important;
    }
    .single-post .page-heading .title{
        line-height:0;
    }
    .single-post .post-heading h2 {
       font-size: 28px;
       line-height: 34px;
    }
    .post-categories{
        display:none;
    }
    footer.footer *{
        text-align:center !important;
    }
    .footer-link {
        width: 50%;
        float: left;
        margin-bottom: 40px;
    }
    footer.footer .mc4wp-form {
       max-width: 100%;
       margin-bottom: 40px;
       margin-top: 40px;
    }
    .mc4wp-form-fields input[type=email]{
        text-align:left !important;
    }
    .process-bottom{
        margin-bottom:40px;
    }
    .home .swiper-entry.wpb_images_carousel{
        margin-top:40px;
    }
    .responsive-margin-top{
        margin-top:30px;
    }
    .team__section .responsive-margin-bottom{
        margin-bottom:1px;
    }
    .mobile-block h2{
        font-size:30px !important;
        font-weight:600 !important;
    }
        
     .responsive-margin-bottom{
        margin-bottom:30px;
    }
    body .work_block{
        margin-right:0 !important;
    }
    .work_block .wpb_column{
        margin-bottom:30px;
    }
    .work_block .wpb_column:last-child{
        margin-bottom:0px;
    }
    body .home-block-title{
        margin-left:0 !important;
    }
    .home-block-title .vc_col-sm-11.mpc-column{
        float: left;
        width: 85%;
    }
    .home-block-title .vc_col-sm-1.mpc-column{
        float: left;
        width: 15%;
    }
    .home-block-title .vc_col-sm-1.mpc-column > .vc_column-inner {
        padding-left:0 !important;
    }
    body .page-heading{
        padding-top: 55px;
        padding-bottom: 55px;
    }
    .page-heading h1.title span{
        font-size:36px;
    }
    body  #breadcrumb{
        margin-bottom:-8px !important;
    }
}
